import React, { useState, useEffect } from 'react';
import axios from 'axios';

// 🟢 වෙනම ෆයිල්ස් වලට නොයා එකම ෆයිල් එකක ලස්සනට Sub-Components විදියට වෙන් කරලා තියෙන්නේ (Standard ක්‍රමයට)

// --- 1. QUIZ MANAGER COMPONENT ---
function TeacherQuiz({ userName, teachingSubject, teachingGrade }) {
  const [quizzes, setQuizzes] = useState([]);
  const [title, setTitle] = useState('');

  const fetchQuizzes = () => {
    axios.get('http://localhost:8081/api/quizzes').then(res => setQuizzes(res.data));
  };
  useEffect(() => { fetchQuizzes(); }, []);

  const handleCreateQuiz = (e) => {
    e.preventDefault();
    const payload = { title, grade: teachingGrade, subject: teachingSubject, teacher_name: userName };
    axios.post('http://localhost:8081/api/add-quiz', payload).then(res => {
      if (res.data.status === "Success") {
        alert("✅ New Quiz Created Successfully!");
        setTitle(''); fetchQuizzes();
      }
    });
  };

  const handleDeleteQuiz = (id) => {
    if (window.confirm("Are you sure you want to delete this quiz paper?")) {
      axios.delete(`http://localhost:8081/api/delete-quiz/${id}`).then(() => fetchQuizzes());
    }
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📝 Manage Quizzes & Exams</h2>
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
        <h4 style={{ margin: '0 0 15px 0', color: '#475569' }}>Create New MCQ Quiz Paper</h4>
        <form onSubmit={handleCreateQuiz} style={{ display: 'flex', gap: '15px' }}>
          <input type="text" placeholder="Enter Quiz Title (e.g., Lesson 02 Evaluation)" value={title} onChange={e => setTitle(e.target.value)} required style={styles.inlineInput} />
          <button type="submit" style={styles.submitBtn}>Create Paper</button>
        </form>
      </div>
      <div style={styles.tableBox}>
        <table style={styles.table}>
          <thead>
            <tr style={styles.thRow}><th>Quiz Title</th><th>Subject & Grade</th><th style={{ textAlign: 'center' }}>Action</th></tr>
          </thead>
          <tbody>
            {quizzes.map(q => (
              <tr key={q.id} style={styles.tdRow}>
                <td style={{ fontWeight: 'bold', color: '#334155' }}>{q.title}</td>
                <td style={{ color: '#475569' }}>{q.subject_name} ({q.grade})</td>
                <td style={{ textAlign: 'center' }}><button onClick={() => handleDeleteQuiz(q.id)} style={styles.actionDelBtn}>🗑️ Delete</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// --- 2. CONTENT MANAGER COMPONENT ---
function TeacherContent({ userName, teachingSubject, materials, fetchData }) {
  const [formTitle, setFormTitle] = useState('');
  const [formGrade, setFormGrade] = useState('Grade 10');
  const [formType, setFormType] = useState('PDF');
  const [formFilePath, setFormFilePath] = useState('');

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const payload = { title: formTitle, material_type: formType, file_path: formFilePath, grade: formGrade, subject: teachingSubject, teacher_name: userName };
    axios.post('http://localhost:8081/api/add-material', payload).then(res => {
      if (res.data.status === "Success") {
        alert("✅ Lesson Material Published!");
        fetchData(); setFormTitle(''); setFormFilePath('');
      }
    });
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📤 Upload Lesson Materials</h2>
      <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
        <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div><label style={styles.label}>Lesson Title</label><input type="text" placeholder="e.g. Introduction to Algebra" value={formTitle} onChange={e => setFormTitle(e.target.value)} required style={styles.fullInput} /></div>
          <div style={{ display: 'flex', gap: '20px' }}>
            <div style={{ flex: 1 }}><label style={styles.label}>Grade Category</label><select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={styles.fullInput}><option>Grade 9</option><option>Grade 10</option><option>Grade 11</option></select></div>
            <div style={{ flex: 1 }}><label style={styles.label}>Material Type</label><select value={formType} onChange={e => setFormType(e.target.value)} style={styles.fullInput}><option value="PDF">PDF Handout</option><option value="Video">Video Lesson</option></select></div>
          </div>
          <div><label style={styles.label}>File Path / YouTube URL</label><input type="text" placeholder="e.g. uploads/notes.pdf" value={formFilePath} onChange={e => setFormFilePath(e.target.value)} required style={styles.fullInput} /></div>
          <button type="submit" style={styles.publishBtn}>+ Publish Lesson</button>
        </form>
      </div>
      <div style={styles.tableBox}>
        <table style={styles.table}>
          <thead>
            <tr style={styles.thRow}><th>Title</th><th>Type</th><th>Grade Target</th><th>Link/Location</th></tr>
          </thead>
          <tbody>
            {materials.map(m => (
              <tr key={m.id} style={styles.tdRow}>
                <td style={{ fontWeight: 'bold' }}>{m.title}</td>
                <td><span style={{ padding: '3px 8px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold', backgroundColor: m.material_type === 'PDF' ? '#fee2e2' : '#e0f2fe', color: m.material_type === 'PDF' ? '#ef4444' : '#0ea5e9' }}>{m.material_type}</span></td>
                <td>{m.grade}</td>
                <td style={{ fontSize: '12px', color: '#64748b' }}>{m.file_path}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// --- 3. MAIN TEACHER DASHBOARD PORTAL ---
export default function TeacherDashboard({ userName, userUsername, subject, qualifications, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [isEditing, setIsEditing] = useState(false);

  const fullSubject = subject || 'Not Set';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 10';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const [profileData, setProfileData] = useState({ 
      name: userName || '', username: userUsername || '', qualifications: qualifications || '',
      email: email || '', phone: phone || '', address: address || '' 
  });

  const fetchData = () => {
    axios.get('http://localhost:8081/api/learning-materials').then(res => setMaterials(res.data));
    axios.get('http://localhost:8081/api/timetable').then(res => {
        setTimetable(res.data.filter(c => c.teacher === userName));
    });
  };

  useEffect(() => {
    fetchData();
    setProfileData({ name: userName, username: userUsername, qualifications: qualifications || 'Government School Teacher', email, phone, address });
  }, [userName, userUsername, qualifications, email, phone, address]);

  const handleProfileUpdate = () => { alert("✅ Profile details updated successfully!"); setIsEditing(false); };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px', boxShadow: '0 4px 15px rgba(21,128,61,0.2)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'relative', zIndex: 2 }}>
                <h1 style={{ margin: '0 0 10px 0', fontSize: '28px' }}>Welcome back, {profileData.name}! 👋</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Your Content Management System is active. Manage your classes and students below.</p>
              </div>
              <div style={{ position: 'absolute', right: '-10px', top: '-40px', fontSize: '150px', opacity: 0.1, zIndex: 1 }}>👨‍🏫</div>
            </div>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" color="#eff6ff" textColor="#3b82f6" />
              <DashboardCard title="Assigned Grades" count={teachingGrade} icon="🏫" color="#f5f3ff" textColor="#7c3aed" />
              <DashboardCard title="Total Students" count="145" icon="🧑‍🎓" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Total Uploaded Content" count={materials.length} icon="📂" color="#fefce8" textColor="#eab308" />
            </div>

            <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '20px' }}>🏫 My Teaching Classes</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                {timetable.map(c => (
                  <div key={c.id} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid #3b82f6` }}>
                    <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{c.grade}</div>
                    <h3 style={{ margin: '0 0 10px 0', color: '#1e293b', fontSize: '18px' }}>{c.subject}</h3>
                    <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 15px 0' }}>🕒 {c.day} ({c.time_slot})</p>
                    <button onClick={() => setActiveTab('upload')} style={styles.classBtn}>📂 Manage Content</button>
                  </div>
                ))}
            </div>
          </div>
        );

      case 'upload':
        return <TeacherContent userName={userName} teachingSubject={teachingSubject} materials={materials} fetchData={fetchData} />;

      case 'quiz':
        return <TeacherQuiz userName={userName} teachingSubject={teachingSubject} teachingGrade={teachingGrade} />;

      case 'forum':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>💬 Discussion Forum</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
                    <input type="text" placeholder="Share an announcement with your classes..." style={styles.fullInput} />
                    <button style={{ padding: '12px 30px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Post</button>
                </div>
                <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '16px' }}>Student Questions</h3>
                <div style={{ padding: '20px', border: '1px solid #e2e8f0', borderRadius: '12px', backgroundColor: '#f8fafc' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                        <span style={{ fontWeight: 'bold', color: '#1e293b', fontSize: '14px' }}>Kasun Perera (Grade 10)</span>
                        <span style={{ fontSize: '12px', color: '#64748b' }}>2 hours ago</span>
                    </div>
                    <p style={{ margin: 0, color: '#475569', fontSize: '14px' }}>Teacher, could you please upload the answers for the Term Test Revision Tute?</p>
                </div>
            </div>
          </div>
        );

      case 'feedback':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>⭐ Student Feedback</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                <div style={{ padding: '20px', borderLeft: '5px solid #eab308', borderRadius: '8px', backgroundColor: '#fefce8' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                        <h4 style={{ margin: '0 0 8px 0', color: '#854d0e', fontSize: '15px' }}>"Great Explanation!"</h4>
                        <span style={{ color: '#eab308' }}>⭐⭐⭐⭐⭐</span>
                    </div>
                    <p style={{ margin: 0, fontSize: '13px', color: '#713f12' }}>The video lesson you uploaded yesterday was very clear. Thank you!</p>
                </div>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>👤 My Profile & Security Settings</h2>
            <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>
                        <h3 style={{ color: '#15803d', margin: 0 }}>Personal Details</h3>
                        {!isEditing ? <button onClick={() => setIsEditing(true)} style={styles.editProfileBtn}>✏️ Edit Profile</button> : <button onClick={handleProfileUpdate} style={styles.saveProfileBtn}>💾 Save</button>}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={styles.label}>Full Name</label><input type="text" value={profileData.name} onChange={(e) => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                        <div><label style={styles.label}>Username</label><input type="text" value={profileData.username} disabled style={{...styles.inputStyleProfile(false), backgroundColor: '#f1f5f9'}} /></div>
                        <div><label style={styles.label}>Qualifications</label><input type="text" value={profileData.qualifications} onChange={(e) => setProfileData({...profileData, qualifications: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                        <div><label style={styles.label}>Email Address</label><input type="email" value={profileData.email} onChange={(e) => setProfileData({...profileData, email: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                        <div><label style={styles.label}>Contact Number</label><input type="text" value={profileData.phone} onChange={(e) => setProfileData({...profileData, phone: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                    </div>
                </div>
                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 20px 0', color: '#ef4444', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>🔑 Change Password</h3>
                    <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={styles.label}>Current Password</label><input type="password" placeholder="Enter current password" style={styles.fullInput} /></div>
                        <div><label style={styles.label}>New Password</label><input type="password" placeholder="Enter new password" style={styles.fullInput} /></div>
                        <button type="button" style={styles.passBtn}>Update Password</button>
                    </form>
                </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', boxShadow: '4px 0 15px rgba(0,0,0,0.1)', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>TEACHER PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'quiz'} onClick={() => setActiveTab('quiz')} icon="📝" text="Quiz Manager" />
          <SidebarBtn active={activeTab === 'forum'} onClick={() => setActiveTab('forum')} icon="💬" text="Student Forum" />
          <SidebarBtn active={activeTab === 'feedback'} onClick={() => setActiveTab('feedback')} icon="⭐" text="View Feedback" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Settings" />
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}><button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout</button></div>
      </div>
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>{renderContent()}</div>
    </div>
  );
}

// --- GLOBAL STYLES & INTERFACES ---
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}>
    <div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px' }}>{count}</h2></div>
    <div style={{ width: '60px', height: '60px', borderRadius: '12px', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '28px' }}>{icon}</div>
  </div>
);

const styles = {
  label: { display: 'block', marginBottom: '8px', color: '#475569', fontSize: '13px', fontWeight: 'bold' },
  inlineInput: { flex: 1, padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' },
  submitBtn: { padding: '12px 25px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' },
  fullInput: { width: '100%', padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '14px' },
  publishBtn: { padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  tableBox: { backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
  thRow: { borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px', height: '40px' },
  tdRow: { borderBottom: '1px solid #f1f5f9', fontSize: '14px', height: '50px' },
  actionDelBtn: { padding: '5px 10px', backgroundColor: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  classBtn: { width: '100%', padding: '10px', backgroundColor: '#f8fafc', color: '#1e293b', border: '1px solid #e2e8f0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px' },
  editProfileBtn: { padding: '8px 16px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  saveProfileBtn: { padding: '8px 16px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  passBtn: { width: '100%', padding: '12px', backgroundColor: '#1e293b', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px' },
  inputStyleProfile: (isEditing) => ({ width: '100%', padding: '12px 15px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b', fontSize: '14px' })
};
